package id.ufal.localnhread;
import android.graphics.Bitmap; import android.os.Bundle; import android.view.*; import android.widget.*; import androidx.annotation.Nullable; import androidx.appcompat.app.AppCompatActivity; import androidx.core.graphics.Insets; import androidx.core.view.*; import java.io.File; import java.util.*; import java.util.concurrent.*;
public final class ReaderActivity extends AppCompatActivity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor(); private ArrayList<String> pages; private File archive; private int current; private ImageView image; private ProgressBar loading; private TextView indicator;
    @Override protected void onCreate(@Nullable Bundle state){super.onCreate(state);setContentView(R.layout.activity_reader);WindowCompat.setDecorFitsSystemWindows(getWindow(),false);View root=findViewById(R.id.readerRoot);ViewCompat.setOnApplyWindowInsetsListener(root,(v,i)->{Insets b=i.getInsets(WindowInsetsCompat.Type.systemBars());v.setPadding(b.left,b.top,b.right,b.bottom);return i;});archive=new File(getIntent().getStringExtra(GalleryActivity.ARCHIVE));pages=getIntent().getStringArrayListExtra(GalleryActivity.PAGES);current=getIntent().getIntExtra(GalleryActivity.START,0);if(pages==null||pages.isEmpty()){finish();return;}image=findViewById(R.id.pageImage);loading=findViewById(R.id.loading);indicator=findViewById(R.id.pageIndicator);findViewById(R.id.previousButton).setOnClickListener(v->showPage(current-1));findViewById(R.id.nextButton).setOnClickListener(v->showPage(current+1));image.setOnClickListener(v->{float x=v.getX();if(x<v.getWidth()/2f)showPage(current-1);else showPage(current+1);});showPage(current);}
    private void showPage(int next){if(next<0||next>=pages.size())return;current=next;final int requested=next;final String pagePath=pages.get(next);loading.setVisibility(View.VISIBLE);indicator.setText((current+1)+" of "+pages.size());worker.execute(()->{try{Bitmap bitmap=CartridgeArchive.page(archive,pagePath,2500);runOnUiThread(()->{if(requested==current)image.setImageBitmap(bitmap);if(requested==current)loading.setVisibility(View.GONE);});}catch(Exception e){runOnUiThread(()->{if(requested==current){loading.setVisibility(View.GONE);Toast.makeText(this,"could not read page.",Toast.LENGTH_LONG).show();}});}});}
    @Override public void onBackPressed(){finish();} @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
